<?php if (!defined('ABSPATH')) { exit; } get_header(); ?>
<main id="main-content" class="container single-main"><?php while (have_posts()) : the_post(); ?>
<article class="article-layout"><header class="article-header"><a class="back-link" href="<?php echo esc_url(home_url('/')); ?>">← Kembali ke beranda</a><?php nh_meta(); ?><h1><?php the_title(); ?></h1><?php if (has_excerpt()) : ?><p class="article-deck"><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?><div class="article-byline"><span class="author-avatar" aria-hidden="true">NH</span><span>Ditulis oleh <strong><?php echo esc_html(nh_author_alias()); ?></strong></span><?php if (get_the_modified_time('U') > get_the_time('U') + 86400) : ?><span class="updated-date">Diperbarui <?php echo esc_html(get_the_modified_date('j M Y')); ?></span><?php endif; ?></div></header>
<?php if (has_post_thumbnail()) : ?><figure class="article-cover"><?php nh_cover('nh-cover', true); ?><?php $caption=wp_get_attachment_caption(get_post_thumbnail_id()); if ($caption) : ?><figcaption><?php echo wp_kses_post($caption); ?></figcaption><?php endif; ?></figure><?php endif; ?>
<div class="article-content"><?php the_content(); wp_link_pages(array('before'=>'<nav class="page-links" aria-label="Halaman artikel">Halaman: ', 'after'=>'</nav>')); ?></div>
<footer class="article-footer"><?php if (has_tag()) : ?><div class="article-tags"><?php the_tags('', ' ', ''); ?></div><?php endif; ?><div class="share-row"><span class="eyebrow">TERUSKAN GAGASANNYA</span><a href="<?php echo esc_url('https://wa.me/?text=' . rawurlencode(get_the_title() . ' ' . get_permalink())); ?>" target="_blank" rel="noopener noreferrer">Bagikan ke WhatsApp ↗</a><button type="button" data-copy-url="<?php echo esc_url(get_permalink()); ?>" hidden>Salin tautan</button><span data-share-status role="status" aria-live="polite"></span></div><p class="correction-note">Ada yang perlu diluruskan? <a href="mailto:nalar.hakim77@gmail.com">Kirim catatan atau koreksi.</a></p></footer>
</article>
<?php get_template_part('template-parts/donation'); ?>
<?php $related=new WP_Query(array('post_type'=>'post','post_status'=>'publish','posts_per_page'=>3,'post__not_in'=>array(get_the_ID()),'category__in'=>wp_get_post_categories(get_the_ID()),'ignore_sticky_posts'=>true,'no_found_rows'=>true)); if ($related->have_posts()) : ?><section class="related-section" aria-labelledby="related-title"><div class="section-heading"><h2 id="related-title">Lanjutkan membaca</h2></div><div class="article-grid"><?php while ($related->have_posts()) : $related->the_post(); get_template_part('template-parts/card'); endwhile; ?></div></section><?php endif; wp_reset_postdata(); ?>
<?php endwhile; ?></main><?php get_footer(); ?>
